<section class="welcome-banner"><div><span class="banner-kicker"><?= e($weekdays[(int)date('w')]) ?> · <?= date('d/m') ?></span><h2>Cada treino conta.<br>Cada detalhe também.</h2><p><?= count($today) ? 'Você tem ' . count($today) . ' atendimento(s) na agenda de hoje.' : 'Sua agenda de hoje está livre para novos movimentos.' ?> Mantenha o foco.</p><a href="<?= url('appointments') ?>">Ver minha agenda <?= icon('arrow') ?></a></div><div class="banner-art" aria-hidden="true"><div class="banner-ring"></div><span class="banner-pulse"><?= icon('pulse') ?></span><span class="banner-pill"><?= icon('check') ?> Um passo à frente.</span></div></section>
