<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Agenda de hoje <span class="count"><?= count($today) ?></span></h2><p>Seus encontros com a evolução.</p></div><a class="text-link" href="<?= url('appointments') ?>">Ver todos <?= icon('arrow') ?></a></div><div class="today-list"><?php foreach ($today as $a): ?><a class="today-item" href="<?= url('appointment-form',['id'=>$a['id']]) ?>"><span class="time-block"><strong><?= substr($a['scheduled_at'],11,5) ?></strong><small><?= $a['duration'] ?> min</small></span><span class="schedule-rule"></span><span class="student-avatar"><?= e(mb_strtoupper(mb_substr($a['student'],0,1))) ?></span><span class="today-student"><strong><?= e($a['student']) ?></strong><small><?= e($a['type']) ?></small></span><span class="badge <?= $a['status']==='Concluído'?'done':'scheduled' ?>"><?= e($a['status']) ?></span></a><?php endforeach; ?><?php if (!$today): ?><div class="empty-state"><?= icon('calendar') ?><h3>Espaço para novos treinos</h3><p>Adicione um atendimento para começar seu dia.</p><a class="text-link" href="<?= url('appointment-form') ?>">Agendar atendimento <?= icon('arrow') ?></a></div><?php endif; ?></div></section>
<section class="panel tasks-panel" id="tasks"><div class="panel-heading"><div><h2>Minhas tarefas <span class="count"><?= $pendingTasks ?></span></h2><p>Pequenos cuidados, grandes diferenças.</p></div><span class="muted-icon"><?= icon('task') ?></span></div><div class="task-list"><?php foreach ($tasks as $task): ?><div class="task-row <?= $task['completed']?'is-completed':'' ?>"><form method="post" action="<?= url('tasks') ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= $task['id'] ?>"><input type="hidden" name="action" value="toggle"><button class="task-check" type="submit" aria-label="<?= $task['completed']?'Reabrir':'Concluir' ?> tarefa: <?= e($task['title']) ?>"><?= $task['completed']?icon('check'):'' ?></button></form><span><?= e($task['title']) ?></span><form method="post" action="<?= url('tasks') ?>" data-confirm="Excluir esta tarefa?"><?= csrf() ?><input type="hidden" name="id" value="<?= $task['id'] ?>"><input type="hidden" name="action" value="delete"><button class="icon-button delete" aria-label="Excluir tarefa: <?= e($task['title']) ?>"><?= icon('trash') ?></button></form></div><?php endforeach; ?><?php if (!$tasks): ?><p class="empty-tasks">Tudo pronto para uma rotina mais organizada. Adicione sua primeira tarefa abaixo.</p><?php endif; ?></div><form class="new-task" method="post" action="<?= url('tasks') ?>"><?= csrf() ?><label class="sr-only" for="task-title">Nova tarefa</label><input id="task-title" name="title" placeholder="Adicionar uma nova tarefa..." minlength="3" maxlength="180" required><button class="icon-button" aria-label="Adicionar tarefa"><?= icon('plus') ?></button></form><div class="task-footer"><?= icon('check') ?> <?= count($tasks)-$pendingTasks ?> de <?= count($tasks) ?> tarefas concluídas</div></section></div>
